values ('mq_unlisted_second_number', 'The Number Beneath the Number', 'mystery', 'B', 'NEUTRAL', 'UNLISTED_WARD', 'Two surveys disagree about the same doorway. The older mark describes a utility district, while the newer mark counts households.', '{"npc_id": "npc_mystery_edda_fen", "name": "Edda Fen", "location": "The Unlisted Ward"}'::jsonb, '{"min_level": 7, "reputation_required": 0, "required_quests": ["mq_unlisted_two_chairs"], "required_items": [], "party_required": false, "raid_size": 1, "mystery": {"schema_version": 1, "pack_id": "xylos_unwritten_witness", "release_status": "client_playable_pending_release", "discovery": {"type": "quest_completed", "quest_id": "mq_unlisted_two_chairs", "region_id": "UNLISTED_WARD"}, "hide_until_discovered": true, "hide_waypoints_until_discovered": true, "decision_required": true, "decision_group": "mq_unlisted_second_number", "choice_ids": ["choice_1", "choice_2", "choice_3"], "enforce_real_interactions": true, "evidence_prop_ids": ["npc_mystery_unlisted_clue_1", "npc_mystery_unlisted_clue_2"]}}'::jsonb, '[{"type": "interact", "target": "npc_mystery_unlisted_clue_1", "count": 1, "description": "Examine Repaired Doorplate and compare its evidence."}, {"type": "interact", "target": "npc_mystery_unlisted_clue_2", "count": 1, "description": "Examine Census Cabinet and compare its evidence."}, {"type": "interact", "target": "npc_mystery_edda_fen", "count": 1, "description": "Discuss your finding with Edda Fen in The Unlisted Ward."}]'::jsonb, '{"exp": 210, "currency": 0, "crd": 70, "reputation": 15, "items": [{"item_id": "mq_relic_unlisted_second_number", "quantity": 1}]}'::jsonb, false, false, 'mq_unlisted_obedient_lock', false, NULL, NULL, NULL, 'quest_mysteries.json', 1)
