values ('mq_unlisted_obedient_lock', 'An Obedient Lock', 'mystery', 'B', 'NEUTRAL', 'UNLISTED_WARD', 'The Ward Indexer repeatedly bars a relief passage because its stale register has no authorized households.', '{"npc_id": "npc_mystery_edda_fen", "name": "Edda Fen", "location": "The Unlisted Ward"}'::jsonb, '{"min_level": 8, "reputation_required": 0, "required_quests": ["mq_unlisted_second_number"], "required_items": [], "party_required": false, "raid_size": 1, "mystery": {"schema_version": 1, "pack_id": "xylos_unwritten_witness", "release_status": "client_playable_pending_release", "discovery": {"type": "quest_completed", "quest_id": "mq_unlisted_second_number", "region_id": "UNLISTED_WARD"}, "hide_until_discovered": true, "hide_waypoints_until_discovered": true, "decision_required": true, "decision_group": "mq_unlisted_obedient_lock", "choice_ids": ["choice_1", "choice_2", "choice_3"], "enforce_real_interactions": true, "evidence_prop_ids": ["npc_mystery_unlisted_clue_1", "npc_mystery_unlisted_clue_2"]}}'::jsonb, '[{"type": "kill", "target": 6101, "count": 1, "description": "Stop the dangerous Malfunctioning Ward Indexer in The Unlisted Ward.", "target_code": "WARD_INDEXER"}, {"type": "travel", "target": "UNLISTED_WARD", "count": 1, "description": "Inspect the now-safe evidence area in The Unlisted Ward."}, {"type": "interact", "target": "npc_mystery_unlisted_clue_1", "count": 1, "description": "Examine Repaired Doorplate and compare its evidence."}, {"type": "interact", "target": "npc_mystery_unlisted_clue_2", "count": 1, "description": "Examine Census Cabinet and compare its evidence."}, {"type": "interact", "target": "npc_mystery_edda_fen", "count": 1, "description": "Discuss your finding with Edda Fen in The Unlisted Ward."}]'::jsonb, '{"exp": 240, "currency": 0, "crd": 80, "reputation": 15, "items": [{"item_id": "mq_relic_unlisted_obedient_lock", "quantity": 1}]}'::jsonb, false, false, 'mq_unlisted_folded_route', false, NULL, NULL, NULL, 'quest_mysteries.json