values ('mq_muster_fourth_beat', 'The Missing Fourth Beat', 'secret', 'A', 'NEUTRAL', 'HOLLOW_MUSTER', 'A four-beat muster signal sounds only three times. A scorch mark could indicate sabotage or an ordinary failure.', '{"npc_id": "npc_mystery_tovan_rell", "name": "Tovan Rell", "location": "Hollow Muster Yard"}'::jsonb, '{"min_level": 18, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "mystery": {"schema_version": 1, "pack_id": "xylos_unwritten_witness", "release_status": "client_playable_pending_release", "discovery": {"type": "item_acquired", "item_id": "mq_clue_muster_1", "region_id": "HOLLOW_MUSTER"}, "hide_until_discovered": true, "hide_waypoints_until_discovered": true, "decision_required": true, "decision_group": "mq_muster_fourth_beat", "choice_ids": ["choice_1", "choice_2", "choice_3"], "enforce_real_interactions": true, "evidence_prop_ids": ["npc_mystery_muster_clue_1", "npc_mystery_muster_clue_2"]}}'::jsonb, '[{"type": "collect", "target": "mq_clue_muster_1", "count": 1, "description": "Recover the Scorched Bell Tally from Hollow Muster Wrecker in Hollow Muster Yard."}, {"type": "interact", "target": "npc_mystery_muster_clue_1", "count": 1, "description": "Examine Split Muster Bell and compare its evidence."}, {"type": "interact", "target": "npc_mystery_muster_clue_2", "count": 1, "description": "Examine Workshop Roll and compare its evidence."}, {"type": "interact", "target": "npc_mystery_tovan_rell", "count": 1, "description": "Discuss your finding with Tovan Rell in Hollow Muster Yard."}]'::jsonb, '{"exp": 540, "currency": 0, "crd": 180, "reputation": 15, "items": [{"item_id": "mq_relic_muster_fourth_beat", "quantity": 1}]}'::jsonb, false, false, 'mq_muster_boots_outward', false, NULL, NULL, NULL, 'quest_mysteries.json', 5)
