values ('mq_muster_boots_outward', 'Boots Facing Outward', 'mystery', 'A', 'NEUTRAL', 'HOLLOW_MUSTER', 'A roll marks a crew absent, but their boots and tool tags suggest an organized civilian evacuation.', '{"npc_id": "npc_mystery_tovan_rell", "name": "Tovan Rell", "location": "Hollow Muster Yard"}'::jsonb, '{"min_level": 18, "reputation_required": 0, "required_quests": ["mq_muster_fourth_beat"], "required_items": [], "party_required": false, "raid_size": 1, "mystery": {"schema_version": 1, "pack_id": "xylos_unwritten_witness", "release_status": "client_playable_pending_release", "discovery": {"type": "quest_completed", "quest_id": "mq_muster_fourth_beat", "region_id": "HOLLOW_MUSTER"}, "hide_until_discovered": true, "hide_waypoints_until_discovered": true, "decision_required": true, "decision_group": "mq_muster_boots_outward", "choice_ids": ["choice_1", "choice_2", "choice_3"], "enforce_real_interactions": true, "evidence_prop_ids": ["npc_mystery_muster_clue_1", "npc_mystery_muster_clue_2"]}}'::jsonb, '[{"type": "interact", "target": "npc_mystery_muster_clue_1", "count": 1, "description": "Examine Split Muster Bell and compare its evidence."}, {"type": "interact", "target": "npc_mystery_muster_clue_2", "count": 1, "description": "Examine Workshop Roll and compare its evidence."}, {"type": "interact", "target": "npc_mystery_tovan_rell", "count": 1, "description": "Discuss your finding with Tovan Rell in Hollow Muster Yard."}]'::jsonb, '{"exp": 540, "currency": 0, "crd": 180, "reputation": 15, "items": [{"item_id": "mq_relic_muster_boots_outward", "quantity": 1}]}'::jsonb, false, false, 'mq_muster_cable_thief', false, NULL, NULL, NULL, 'quest_mysteries.json', 6)
