values ('mq_muster_cable_thief', 'What Keeps Taking the Cable', 'mystery', 'A', 'NEUTRAL', 'HOLLOW_MUSTER', 'Every repaired bell cable disappears. Tovan needs the malfunctioning wrecker stopped before anyone can rely on the signal.', '{"npc_id": "npc_mystery_tovan_rell", "name": "Tovan Rell", "location": "Hollow Muster Yard"}'::jsonb, '{"min_level": 19, "reputation_required": 0, "required_quests": ["mq_muster_boots_outward"], "required_items": [], "party_required": false, "raid_size": 1, "mystery": {"schema_version": 1, "pack_id": "xylos_unwritten_witness", "release_status": "client_playable_pending_release", "discovery": {"type": "quest_completed", "quest_id": "mq_muster_boots_outward", "region_id": "HOLLOW_MUSTER"}, "hide_until_discovered": true, "hide_waypoints_until_discovered": true, "decision_required": true, "decision_group": "mq_muster_cable_thief", "choice_ids": ["choice_1", "choice_2", "choice_3"], "enforce_real_interactions": true, "evidence_prop_ids": ["npc_mystery_muster_clue_1", "npc_mystery_muster_clue_2"]}}'::jsonb, '[{"type": "kill", "target": 6102, "count": 1, "description": "Stop the dangerous Hollow Muster Wrecker in Hollow Muster Yard.", "target_code": "HOLLOW_MUSTER_WRECKER"}, {"type": "travel", "target": "HOLLOW_MUSTER", "count": 1, "description": "Inspect the now-safe evidence area in Hollow Muster Yard."}, {"type": "interact", "target": "npc_mystery_muster_clue_1", "count": 1, "description": "Examine Split Muster Bell and compare its evidence."}, {"type": "interact", "target": "npc_mystery_muster_clue_2", "count": 1, "description": "Examine Workshop Roll and compare its evidence."}, {"type": "interact", "target": "npc_mystery_tovan_rell", "count": 1, "description": "Discuss your finding with Tovan Rell in Hollow Muster Yard."}]'::jsonb, '{"exp": 570, "currency": 0, "crd": 190, "reputation": 15, "items": [{"item_id": "mq_relic_muster_cable_thief", "quantity": 1}]}'::jsonb, false, false, 'mq_muster_shared_shift', false, NULL, NULL, NULL, 'ques