values ('mq_muster_shared_shift', 'The Shift Neither Banner Claimed', 'secret', 'A', 'NEUTRAL', 'HOLLOW_MUSTER', 'The evacuation roll includes workers supplied by two rival institutions. A single-banner memorial would erase half the crew.', '{"npc_id": "npc_mystery_tovan_rell", "name": "Tovan Rell", "location": "Hollow Muster Yard"}'::jsonb, '{"min_level": 20, "reputation_required": 0, "required_quests": ["mq_muster_cable_thief"], "required_items": [], "party_required": false, "raid_size": 1, "mystery": {"schema_version": 1, "pack_id": "xylos_unwritten_witness", "release_status": "client_playable_pending_release", "discovery": {"type": "quest_completed", "quest_id": "mq_muster_cable_thief", "region_id": "HOLLOW_MUSTER"}, "hide_until_discovered": true, "hide_waypoints_until_discovered": true, "decision_required": true, "decision_group": "mq_muster_shared_shift", "choice_ids": ["choice_1", "choice_2", "choice_3"], "enforce_real_interactions": true, "evidence_prop_ids": ["npc_mystery_muster_clue_1", "npc_mystery_muster_clue_2"]}}'::jsonb, '[{"type": "collect", "target": "mq_clue_muster_2", "count": 1, "description": "Recover the Workshop Evacuation Roll from Hollow Muster Wrecker in Hollow Muster Yard."}, {"type": "interact", "target": "npc_mystery_muster_clue_1", "count": 1, "description": "Examine Split Muster Bell and compare its evidence."}, {"type": "interact", "target": "npc_mystery_muster_clue_2", "count": 1, "description": "Examine Workshop Roll and compare its evidence."}, {"type": "interact", "target": "npc_mystery_tovan_rell", "count": 1, "description": "Discuss your finding with Tovan Rell in Hollow Muster Yard."}]'::jsonb, '{"exp": 600, "currency": 0, "crd": 200, "reputation": 15, "items": [{"item_id": "mq_relic_muster_shared_shift", "quantity": 1}]}'::jsonb, false, false, 'mq_muster_warning_not_oath', false, NULL, NULL, NULL, 'quest_mysteries.json', 8)
