values ('mq_quiet_cloth_on_crystal', 'Cloth on a Singing Rib', 'secret', 'A', 'NEUTRAL', 'QUIET_RESONATOR', 'A cloth-wrapped rib sounds different from its neighbors. Iren asks whether deliberate damping was care, damage, or concealment.', '{"npc_id": "npc_mystery_iren_saye", "name": "Iren Saye", "location": "Quiet Resonator Gallery"}'::jsonb, '{"min_level": 32, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "mystery": {"schema_version": 1, "pack_id": "xylos_unwritten_witness", "release_status": "client_playable_pending_release", "discovery": {"type": "item_acquired", "item_id": "mq_clue_quiet_1", "region_id": "QUIET_RESONATOR"}, "hide_until_discovered": true, "hide_waypoints_until_discovered": true, "decision_required": true, "decision_group": "mq_quiet_cloth_on_crystal", "choice_ids": ["choice_1", "choice_2", "choice_3"], "enforce_real_interactions": true, "evidence_prop_ids": ["npc_mystery_quiet_clue_1", "npc_mystery_quiet_clue_2"]}}'::jsonb, '[{"type": "collect", "target": "mq_clue_quiet_1", "count": 1, "description": "Recover the Cloth-Bound Resonance Trace from Quiet Gallery Rift Beast in Quiet Resonator Gallery."}, {"type": "interact", "target": "npc_mystery_quiet_clue_1", "count": 1, "description": "Examine Wrapped Resonator Rib and compare its evidence."}, {"type": "interact", "target": "npc_mystery_quiet_clue_2", "count": 1, "description": "Examine Drainage Listening Bench and compare its evidence."}, {"type": "interact", "target": "npc_mystery_iren_saye", "count": 1, "description": "Discuss your finding with Iren Saye in Quiet Resonator Gallery."}]'::jsonb, '{"exp": 960, "currency": 0, "crd": 320, "reputation": 15, "items": [{"item_id": "mq_relic_quiet_cloth_on_crystal", "quantity": 1}]}'::jsonb, false, false, 'mq_quiet_bench_wrong_way', false, NULL, NULL, NULL, 'quest_mysteries.json', 15)
