values ('mq_armistice_modern_lock', 'A Modern Lock on Ancient Stone', 'secret', 'S', 'NEUTRAL', 'SEALED_ARMISTICE_VAULT', 'A modern custody lock conceals a relief archive inside an ancient chamber. Maela needs the two histories separated before rumors combine them.', '{"npc_id": "npc_mystery_maela_orr", "name": "Maela Orr", "location": "Sealed Armistice Vault"}'::jsonb, '{"min_level": 65, "reputation_required": 0, "required_quests": [], "required_items": [], "party_required": false, "raid_size": 1, "mystery": {"schema_version": 1, "pack_id": "xylos_unwritten_witness", "release_status": "client_playable_pending_release", "discovery": {"type": "item_acquired", "item_id": "mq_clue_armistice_1", "region_id": "SEALED_ARMISTICE_VAULT"}, "hide_until_discovered": true, "hide_waypoints_until_discovered": true, "decision_required": true, "decision_group": "mq_armistice_modern_lock", "choice_ids": ["choice_1", "choice_2", "choice_3"], "enforce_real_interactions": true, "evidence_prop_ids": ["npc_mystery_armistice_clue_1", "npc_mystery_armistice_clue_2"]}}'::jsonb, '[{"type": "collect", "target": "mq_clue_armistice_1", "count": 1, "description": "Recover the Scorched Relief Ledger Leaf from Vault Ember Drakonid in Sealed Armistice Vault."}, {"type": "interact", "target": "npc_mystery_armistice_clue_1", "count": 1, "description": "Examine Scorched Relief Ledger and compare its evidence."}, {"type": "interact", "target": "npc_mystery_armistice_clue_2", "count": 1, "description": "Examine Duplicate Custody Plate and compare its evidence."}, {"type": "interact", "target": "npc_mystery_maela_orr", "count": 1, "description": "Discuss your finding with Maela Orr in Sealed Armistice Vault."}]'::jsonb, '{"exp": 1950, "currency": 0, "crd": 650, "reputation": 15, "items": [{"item_id": "mq_relic_armistice_modern_lock", "quantity": 1}]}'::jsonb, false, false, 'mq_armistice_burn_without_verdict', false, NULL, NULL, NULL, 'quest_mysteries.json', 20)
