values ('mq_armistice_safe_for_copy', 'Safe Enough to Make a Copy', 'mystery', 'S', 'NEUTRAL', 'SEALED_ARMISTICE_VAULT', 'The nesting drakonid threatens anyone copying the relief records. Maela needs a safe chamber before commissioning an audit.', '{"npc_id": "npc_mystery_maela_orr", "name": "Maela Orr", "location": "Sealed Armistice Vault"}'::jsonb, '{"min_level": 68, "reputation_required": 0, "required_quests": ["mq_armistice_burn_without_verdict"], "required_items": [], "party_required": false, "raid_size": 1, "mystery": {"schema_version": 1, "pack_id": "xylos_unwritten_witness", "release_status": "client_playable_pending_release", "discovery": {"type": "quest_completed", "quest_id": "mq_armistice_burn_without_verdict", "region_id": "SEALED_ARMISTICE_VAULT"}, "hide_until_discovered": true, "hide_waypoints_until_discovered": true, "decision_required": true, "decision_group": "mq_armistice_safe_for_copy", "choice_ids": ["choice_1", "choice_2", "choice_3"], "enforce_real_interactions": true, "evidence_prop_ids": ["npc_mystery_armistice_clue_1", "npc_mystery_armistice_clue_2"]}}'::jsonb, '[{"type": "kill", "target": 6105, "count": 1, "description": "Stop the dangerous Vault Ember Drakonid in Sealed Armistice Vault.", "target_code": "VAULT_EMBER_DRAKONID"}, {"type": "travel", "target": "SEALED_ARMISTICE_VAULT", "count": 1, "description": "Inspect the now-safe evidence area in Sealed Armistice Vault."}, {"type": "interact", "target": "npc_mystery_armistice_clue_1", "count": 1, "description": "Examine Scorched Relief Ledger and compare its evidence."}, {"type": "interact", "target": "npc_mystery_armistice_clue_2", "count": 1, "description": "Examine Duplicate Custody Plate and compare its evidence."}, {"type": "interact", "target": "npc_mystery_maela_orr", "count": 1, "description": "Discuss your finding with Maela Orr in Sealed Armistice Vault."}]'::jsonb, '{"exp": 2040, "currency": 0, "crd": 680, "reputation": 15, "items": [{"item_id": "mq_relic_armistice_safe_for_copy", "quantity": 1}]}'::jsonb, false, false, 'mq_armistice_reserve_not_ransom', false, NULL, NULL, NULL, 'quest_mysteries.json', 22)
