values ('mq_armistice_reserve_not_ransom', 'The Reserve That Wasn''t a Ransom', 'secret', 'S', 'NEUTRAL', 'SEALED_ARMISTICE_VAULT', 'A line called withheld reserve looks like relief money seized as leverage. The duplicate identifies an unsettled payment, while leaving the delay''s human cost visible.', '{"npc_id": "npc_mystery_maela_orr", "name": "Maela Orr", "location": "Sealed Armistice Vault"}'::jsonb, '{"min_level": 70, "reputation_required": 0, "required_quests": ["mq_armistice_safe_for_copy"], "required_items": [], "party_required": false, "raid_size": 1, "mystery": {"schema_version": 1, "pack_id": "xylos_unwritten_witness", "release_status": "client_playable_pending_release", "discovery": {"type": "quest_completed", "quest_id": "mq_armistice_safe_for_copy", "region_id": "SEALED_ARMISTICE_VAULT"}, "hide_until_discovered": true, "hide_waypoints_until_discovered": true, "decision_required": true, "decision_group": "mq_armistice_reserve_not_ransom", "choice_ids": ["choice_1", "choice_2", "choice_3"], "enforce_real_interactions": true, "evidence_prop_ids": ["npc_mystery_armistice_clue_1", "npc_mystery_armistice_clue_2"]}}'::jsonb, '[{"type": "collect", "target": "mq_clue_armistice_2", "count": 1, "description": "Recover the Modern Custody Duplicate from Vault Ember Drakonid in Sealed Armistice Vault."}, {"type": "interact", "target": "npc_mystery_armistice_clue_1", "count": 1, "description": "Examine Scorched Relief Ledger and compare its evidence."}, {"type": "interact", "target": "npc_mystery_armistice_clue_2", "count": 1, "description": "Examine Duplicate Custody Plate and compare its evidence."}, {"type": "interact", "target": "npc_mystery_maela_orr", "count": 1, "description": "Discuss your finding with Maela Orr in Sealed Armistice Vault."}]'::jsonb, '{"exp": 2100, "currency": 0, "crd": 700, "reputation": 15, "items": [{"item_id": "mq_relic_armistice_reserve_not_ransom", "quantity": 1}]}'::jsonb, false, false, 'mq_armistice_unwritten_witness', false, NULL, N