values ('mq_armistice_unwritten_witness', 'The Unwritten Witness', 'mystery', 'S', 'NEUTRAL', 'SEALED_ARMISTICE_VAULT', 'Records from the ward, yard, berth, gallery, and vault show how institutions can mistake absence, silence, or delay for consent. Maela offers no revelation about a hidden ruler, only a decision about who may challenge the archive.', '{"npc_id": "npc_mystery_maela_orr", "name": "Maela Orr", "location": "Sealed Armistice Vault"}'::jsonb, '{"min_level": 75, "reputation_required": 0, "required_quests": ["mq_armistice_reserve_not_ransom", "mq_unlisted_right_to_remain", "mq_muster_warning_not_oath", "mq_zero_port_without_lie", "mq_quiet_silence_kept"], "required_items": [], "party_required": false, "raid_size": 1, "mystery": {"schema_version": 1, "pack_id": "xylos_unwritten_witness", "release_status": "client_playable_pending_release", "discovery": {"type": "quest_completed", "quest_id": "mq_armistice_reserve_not_ransom", "region_id": "SEALED_ARMISTICE_VAULT"}, "hide_until_discovered": true, "hide_waypoints_until_discovered": true, "decision_required": true, "decision_group": "mq_armistice_unwritten_witness", "choice_ids": ["choice_1", "choice_2", "choice_3"], "enforce_real_interactions": true, "evidence_prop_ids": ["npc_mystery_armistice_clue_1", "npc_mystery_armistice_clue_2"]}}'::jsonb, '[{"type": "interact", "target": "npc_mystery_armistice_clue_1", "count": 1, "description": "Examine Scorched Relief Ledger and compare its evidence."}, {"type": "interact", "target": "npc_mystery_armistice_clue_2", "count": 1, "description": "Examine Duplicate Custody Plate and compare its evidence."}, {"type": "interact", "target": "npc_mystery_maela_orr", "count": 1, "description": "Discuss your finding with Maela Orr in Sealed Armistice Vault."}]'::jsonb, '{"exp": 2250, "currency": 0, "crd": 750, "reputation": 40, "items": [{"item_id": "mq_relic_armistice_unwritten_witness", "quantity": 1}]}'::jsonb, false, false, NULL, false, NULL, NULL, NULL, 'quest_mysteries.json', 24)
