values ('dialog_mq_muster_fourth_beat', 'mq_muster_fourth_beat', 'npc_mystery_tovan_rell', 'greeting', '[{"id": "greeting", "text": "Three beats call a shift. Four clear the yard. Listen before you accuse someone of desertion.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "The tally labels the fourth beat evacuate. A missing cable reaches the workshop, not the barracks. Boots point toward an exit rather than the parade ground.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "A four-beat muster signal sounds only three times. A scorch mark could indicate sabotage or an ordinary failure.", "options": [{"text": "Restore the evacuation signal first", "next": "choice_1", "action": ""}, {"text": "Post a visual warning alongside repairs", "next": "choice_2", "action": ""}, {"text": "Use a staffed manual bell", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: Workers hear a full warning sequence. The cost is clear: Production waits while crews test it.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: A second warning channel is established. The cost is clear: Someone must maintain the signs.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: The warning no longer depends on one cable. The cost is clear: A worker must remain on watch.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Recover the Scorched Bell Tally from Hollow Muster Wrecker in Hollow Muster Yard. Examine Split Muster Bell and compare its evidence. Examine Workshop Roll and compare its evidence. Discuss your finding with Tovan Rell in Hollow Muster Yard.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 833)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_muster_boots_outward', 'mq_muster_boots_outward', 'npc_mystery_tovan_rell', 'greeting', '[{"id": "greeting", "text": "An empty parade line doesn''t tell you where they went. Look at the wear on the soles.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "Boot soles carry workshop grit, not barracks polish. Tool tags follow a work roster, not a military rank. The roll records departure after the evacuation beat.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "A roll marks a crew absent, but their boots and tool tags suggest an organized civilian evacuation.", "options": [{"text": "Correct the work roster publicly", "next": "choice_1", "action": ""}, {"text": "Attach witness statements privately", "next": "choice_2", "action": ""}, {"text": "Let the crew speak collectively", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: Civilian absences become documented evacuations. The cost is clear: Employers must acknowledge the mistake.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: Workers gain a restricted proof of departure. The cost is clear: Public suspicion may persist longer.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: The roll carries their own account. The cost is clear: The crew must spend time organizing.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Examine Split Muster Bell and compare its evidence. Examine Workshop Roll and compare its evidence. Discuss your finding with Tovan Rell in Hollow Muster Yard.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 834)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_muster_cable_thief', 'mq_muster_cable_thief', 'npc_mystery_tovan_rell', 'greeting', '[{"id": "greeting", "text": "Same length missing. Same bite in the copper. Someone calls it sabotage; I call it a repair that hasn''t found its cause.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "Cable ends show mechanical shearing, not a clean hand cut. The wrecker''s cargo cradle contains matching wire. Its salvage route loops through the bell support.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "Every repaired bell cable disappears. Tovan needs the malfunctioning wrecker stopped before anyone can rely on the signal.", "options": [{"text": "Document the mechanical cause", "next": "choice_1", "action": ""}, {"text": "Invite both crews to inspect it", "next": "choice_2", "action": ""}, {"text": "Retain the damaged cable as proof", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: Tovan files a repair failure, not a faction charge. The cost is clear: A politically useful accusation loses force.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: Rival crews share a witnessed fault report. The cost is clear: Inspection delays reopening.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: The physical evidence survives the repair. The cost is clear: The workshop must store it.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Stop the dangerous Hollow Muster Wrecker in Hollow Muster Yard. Inspect the now-safe evidence area in Hollow Muster Yard. Examine Split Muster Bell and compare its evidence. Examine Workshop Roll and compare its evidence. Discuss your finding with Tovan Rell in Hollow Muster Yard.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 835)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_muster_shared_shift', 'mq_muster_shared_shift', 'npc_mystery_tovan_rell', 'greeting', '[{"id": "greeting", "text": "They held the same rope. Their employers can argue about the brass plaque after I finish the names.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "The roll interleaves two supply stamps. All entries share one shift and one exit record. A margin note identifies the common bell crew, not a new faction.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "The evacuation roll includes workers supplied by two rival institutions. A single-banner memorial would erase half the crew.", "options": [{"text": "List names without institutional marks", "next": "choice_1", "action": ""}, {"text": "Keep both supply stamps", "next": "choice_2", "action": ""}, {"text": "Place separate plaques beside one bell", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: The memorial centers the workers. The cost is clear: The sponsors lose visible credit.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: Both contributions remain documented. The cost is clear: Visitors may read politics into the plaque.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: Each institution keeps its record at a common site. The cost is clear: The shared work is less immediately obvious.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Recover the Workshop Evacuation Roll from Hollow Muster Wrecker in Hollow Muster Yard. Examine Split Muster Bell and compare its evidence. Examine Workshop Roll and compare its evidence. Discuss your finding with Tovan Rell in Hollow Muster Yard.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 836)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_muster_warning_not_oath', 'mq_muster_warning_not_oath', 'npc_mystery_tovan_rell', 'greeting', '[{"id": "greeting", "text": "A monument rings when someone important visits. A warning rings when someone ordinary is in danger. Which job are we paying for?", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "The fourth beat has a specific safety meaning. The absent crew obeyed it. The wrecker fault explains why the warning failed.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "The repaired bell can become a ceremonial monument or a working civilian warning. Tovan cannot maintain both roles without help.", "options": [{"text": "Keep it a working warning bell", "next": "choice_1", "action": ""}, {"text": "Move the original into a memorial", "next": "choice_2", "action": ""}, {"text": "Give maintenance to a joint work council", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: The yard retains its evacuation signal. The cost is clear: A crew must fund regular checks.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: The original becomes evidence beside a working copy. The cost is clear: A replacement must carry the warning.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: The bell gains shared civilian custodians. The cost is clear: Rival crews must keep cooperating.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Examine Split Muster Bell and compare its evidence. Examine Workshop Roll and compare its evidence. Discuss your finding with Tovan Rell in Hollow Muster Yard.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 837)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
