values ('dialog_npc_mystery_zero_clue_1', NULL, 'npc_mystery_zero_clue_1', 'greet', '[{"id": "greet", "text": "A berth marked zero contains a crate with an inward-facing shipping stencil. A polished scale shows the same value even with no cargo.", "options": [{"text": "Examine the mark.", "next": "detail", "action": ""}, {"text": "Compare its placement.", "next": "placement", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "detail", "text": "The stencil faces the crate interior.", "options": [{"text": "Look at its setting.", "next": "placement", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "placement", "text": "A berth marked zero contains a crate with an inward-facing shipping stencil. A polished scale shows the same value even with no cargo.", "options": [{"text": "Look again.", "next": "greet", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The record is left in place.", "options": []}]'::jsonb, 'dialog_tree_master.json', 119)
