values ('dialog_mq_zero_weight_nothing', 'mq_zero_weight_nothing', 'npc_mystery_sella_quinn', 'greeting', '[{"id": "greeting", "text": "Empty doesn''t mean free. It also doesn''t mean fraud. Show me what the contract actually sold.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "The cargo column is blank, not marked lost. The billed unit is berth-day, not mass. The empty scale retains its tare reading.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "A manifest prices an apparently empty crate. Sella suspects the buyer purchased storage space, not goods.", "options": [{"text": "Disclose the storage unit prominently", "next": "choice_1", "action": ""}, {"text": "Offer a partial refund for ambiguity", "next": "choice_2", "action": ""}, {"text": "Keep the contract and add an explanation", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: Future buyers see what is being sold. The cost is clear: The broker loses an easy sales shorthand.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: The buyer receives compensation without a fraud finding. The cost is clear: The seller bears a negotiation cost.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: The annex records a clarified but unchanged agreement. The cost is clear: The buyer still pays its stated fee.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Recover the Blank-Cargo Manifest from Zero Berth Extortionist in Zero Berth Customs Annex. Examine Zero Berth Scale and compare its evidence. Examine Reversed Shipping Stencil and compare its evidence. Discuss your finding with Sella Quinn in Zero Berth Customs Annex.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 838)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_zero_inside_label', 'mq_zero_inside_label', 'npc_mystery_sella_quinn', 'greeting', '[{"id": "greeting", "text": "Serial''s genuine. Story''s facing the wrong way. Turn your attention, not the number.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "The stencil faces the crate interior. The scale log marks outbound packaging as returnable. The repeated serial refers to the container, not two cargo loads.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "An inward stencil makes a returnable container look like a new delivery. Its direction matters more than its serial number.", "options": [{"text": "Correct the delivery count", "next": "choice_1", "action": ""}, {"text": "Flag the stencil for physical inspection", "next": "choice_2", "action": ""}, {"text": "Publish a return-label standard", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: The record separates container returns from goods. The cost is clear: The carrier''s volume claim shrinks.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: An inspector confirms direction before settlement. The cost is clear: A shipment waits at the berth.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: A clearer standard prevents the same dispute. The cost is clear: Dock crews must relabel stock.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Examine Zero Berth Scale and compare its evidence. Examine Reversed Shipping Stencil and compare its evidence. Discuss your finding with Sella Quinn in Zero Berth Customs Annex.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 839)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_zero_fee_at_door', 'mq_zero_fee_at_door', 'npc_mystery_sella_quinn', 'greeting', '[{"id": "greeting", "text": "They charge to let me inspect the fee they charge. Stop that little circle. Leave the innocent crews out of it.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "The demanded fee is absent from the signed contract. The collector bars only the inspection door. The invoice identifies a private collector, not a faction decree.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "An extortionist blocks examination of the disputed invoices. Sella needs access, not a verdict about the whole port.", "options": [{"text": "File the unauthorized fee with witnesses", "next": "choice_1", "action": ""}, {"text": "Protect the witnesses'' identities", "next": "choice_2", "action": ""}, {"text": "Send the physical invoices to neutral custody", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: The collector''s obstruction becomes a documented claim. The cost is clear: Witnesses must risk being identified.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: Sella submits a restricted statement. The cost is clear: The case needs a trusted intermediary.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: A neutral examiner receives the originals. The cost is clear: Settlement is delayed by transport.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Stop the dangerous Zero Berth Extortionist in Zero Berth Customs Annex. Inspect the now-safe evidence area in Zero Berth Customs Annex. Examine Zero Berth Scale and compare its evidence. Examine Reversed Shipping Stencil and compare its evidence. Discuss your finding with Sella Quinn in Zero Berth Customs Annex.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 840)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_zero_rent_inside_rent', 'mq_zero_rent_inside_rent', 'npc_mystery_sella_quinn', 'greeting', '[{"id": "greeting", "text": "We found a real service. Now we''ve found it twice on the same day''s bill. One honest line doesn''t excuse the second.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "Both invoices cover the same interval. The nested line references the already settled container charge. No additional berth or handling event appears in the log.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "A valid storage contract has been billed twice by nesting an already paid container-day charge inside berth rent.", "options": [{"text": "Refund the duplicate charge", "next": "choice_1", "action": ""}, {"text": "Credit the buyer''s next storage booking", "next": "choice_2", "action": ""}, {"text": "Place the duplicate sum in neutral escrow", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: The corrected account preserves the original service fee. The cost is clear: The creditor loses claimed revenue.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: The account carries a compensating credit. The cost is clear: Relief depends on using the port again.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: Neither party can spend the disputed amount yet. The cost is clear: Both sides wait for review.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Recover the Nested Storage Invoice from Zero Berth Extortionist in Zero Berth Customs Annex. Examine Zero Berth Scale and compare its evidence. Examine Reversed Shipping Stencil and compare its evidence. Discuss your finding with Sella Quinn in Zero Berth Customs Annex.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 841)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_zero_port_without_lie', 'mq_zero_port_without_lie', 'npc_mystery_sella_quinn', 'greeting', '[{"id": "greeting", "text": "A scandal sells faster than a standard. Tell me which one will still help the next dockhand.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "The storage unit is valid. The reversed label explains the crate''s journey. The overlapping invoice interval proves the specific error.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "A corrected claim can become a public precedent, a private settlement, or a monitored trial. Each protects different people.", "options": [{"text": "Publish an anonymized precedent", "next": "choice_1", "action": ""}, {"text": "Negotiate a private settlement", "next": "choice_2", "action": ""}, {"text": "Run a jointly monitored billing trial", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: The berth displays a general billing correction. The cost is clear: The buyer''s personal story stays absent.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: The parties settle without revealing their identities. The cost is clear: Future buyers lack a public precedent.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: Meridian and OmniCorp participants compare a limited test. The cost is clear: Workers must keep an extra record.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Examine Zero Berth Scale and compare its evidence. Examine Reversed Shipping Stencil and compare its evidence. Discuss your finding with Sella Quinn in Zero Berth Customs Annex.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 842)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mystery_quiet_greet', NULL, 'npc_mystery_iren_saye', 'greet', '[{"id": "greet", "text": "We heard it. We haven''t explained it. Three resonant ribs surround a fourth rib wrapped in old cloth. A listening bench faces away from the visible crystals toward a drainage channel.", "options": [{"text": "What did you notice here?", "next": "observation", "action": ""}, {"text": "Why ask an outsider?", "next": "motive", "action": ""}, {"text": "I will look around first.", "next": "exit", "action": "exit"}]}, {"id": "observation", "text": "Cloth touches the fourth rib at a vibration point.", "options": [{"text": "Tell me more.", "next": "greet", "action": ""}, {"text": "I will examine it.", "next": "exit", "action": "exit"}]}, {"id": "motive", "text": "Iren wants a witness willing to compare Arcanum measurements with Children of the Shard oral accounts without appropriating either or declaring the Shard conscious.", "options": [{"text": "What did you notice?", "next": "observation", "action": ""}, {"text": "I will think about it.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The evidence remains available when you return.", "options": []}]'::jsonb, 'dialog_tree_master.json', 121)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_npc_mystery_quiet_clue_1', NULL, 'npc_mystery_quiet_clue_1', 'greet', '[{"id": "greet", "text": "Three resonant ribs surround a fourth rib wrapped in old cloth. A listening bench faces away from the visible crystals toward a drainage channel.", "options": [{"text": "Examine the mark.", "next": "detail", "action": ""}, {"text": "Compare its placement.", "next": "placement", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "detail", "text": "The bench faces the drainage channel.", "options": [{"text": "Look at its setting.", "next": "placement", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "placement", "text": "Three resonant ribs surround a fourth rib wrapped in old cloth. A listening bench faces away from the visible crystals toward a drainage channel.", "options": [{"text": "Look again.", "next": "greet", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The record is left in place.", "options": []}]'::jsonb, 'dialog_tree_master.json', 122)
