values ('dialog_npc_mystery_quiet_clue_2', NULL, 'npc_mystery_quiet_clue_2', 'greet', '[{"id": "greet", "text": "A delayed note is loudest near its opening.", "options": [{"text": "Examine the mark.", "next": "detail", "action": ""}, {"text": "Compare its placement.", "next": "placement", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "detail", "text": "A delayed note is loudest near its opening.", "options": [{"text": "Look at its setting.", "next": "placement", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "placement", "text": "Three resonant ribs surround a fourth rib wrapped in old cloth. A listening bench faces away from the visible crystals toward a drainage channel.", "options": [{"text": "Look again.", "next": "greet", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The record is left in place.", "options": []}]'::jsonb, 'dialog_tree_master.json', 123)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
