values ('dialog_mq_quiet_cloth_on_crystal', 'mq_quiet_cloth_on_crystal', 'npc_mystery_iren_saye', 'greeting', '[{"id": "greeting", "text": "Someone softened this note. Before we call it vandalism or a miracle, let''s hear what they changed.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "Cloth touches the fourth rib at a vibration point. The trace records lower amplitude, not a new word. The cloth''s wear suggests repeated maintenance.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "A cloth-wrapped rib sounds different from its neighbors. Iren asks whether deliberate damping was care, damage, or concealment.", "options": [{"text": "Keep the damping while measuring", "next": "choice_1", "action": ""}, {"text": "Remove it briefly with consent", "next": "choice_2", "action": ""}, {"text": "Make a nonintrusive external trace", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: The caretaker''s intervention stays intact. The cost is clear: The unwrapped tone remains untested.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: A limited comparison is recorded. The cost is clear: The louder tone may disturb visitors.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: The study avoids changing the rib. The cost is clear: The result has more uncertainty.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Recover the Cloth-Bound Resonance Trace from Quiet Gallery Rift Beast in Quiet Resonator Gallery. Examine Wrapped Resonator Rib and compare its evidence. Examine Drainage Listening Bench and compare its evidence. Discuss your finding with Iren Saye in Quiet Resonator Gallery.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 843)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_quiet_bench_wrong_way', 'mq_quiet_bench_wrong_way', 'npc_mystery_iren_saye', 'greeting', '[{"id": "greeting", "text": "The view is terrible. The listening position is excellent. Whoever sat here knew the difference.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "The bench faces the drainage channel. A delayed note is loudest near its opening. The rib-facing seat receives the first note but not the delay clearly.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "A listening bench faces a drain instead of the crystals. Its placement suggests the apparent reply has a second path.", "options": [{"text": "Mark the reflection path publicly", "next": "choice_1", "action": ""}, {"text": "Discuss it with the oral custodians first", "next": "choice_2", "action": ""}, {"text": "Publish the measurement without a verdict", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: Visitors can compare both listening positions. The cost is clear: A cherished interpretation may be challenged.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: The explanation begins with the people who preserve the account. The cost is clear: Public correction waits.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: The record separates timing from claims about a voice. The cost is clear: Readers may still overinterpret it.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Examine Wrapped Resonator Rib and compare its evidence. Examine Drainage Listening Bench and compare its evidence. Discuss your finding with Iren Saye in Quiet Resonator Gallery.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 844)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_quiet_test_without_beast', 'mq_quiet_test_without_beast', 'npc_mystery_iren_saye', 'greeting', '[{"id": "greeting", "text": "It''s defending a nest. That doesn''t make it a prophet. Clear the unsafe channel; don''t write a revelation into the claws.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "Claw marks reach nesting debris in the channel. The interference follows movement, not the rib''s note. The undisturbed trace still shows a reflection delay.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "A rift beast blocks the listening channel. Iren needs a safe test environment, not a ritual victory.", "options": [{"text": "Limit future tests to a marked safe interval", "next": "choice_1", "action": ""}, {"text": "Move observers to the outer bench", "next": "choice_2", "action": ""}, {"text": "Suspend invasive testing", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: The gallery receives a bounded test schedule. The cost is clear: The study collects fewer samples.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: The risky channel no longer hosts visitors. The cost is clear: Measurements become less precise.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: Iren keeps the known result without expanding the disturbance. The cost is clear: The cause remains less fully characterized.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Stop the dangerous Quiet Gallery Rift Beast in Quiet Resonator Gallery. Inspect the now-safe evidence area in Quiet Resonator Gallery. Examine Wrapped Resonator Rib and compare its evidence. Examine Drainage Listening Bench and compare its evidence. Discuss your finding with Iren Saye in Quiet Resonator Gallery.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 845)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_quiet_same_pause', 'mq_quiet_same_pause', 'npc_mystery_iren_saye', 'greeting', '[{"id": "greeting", "text": "Two answers, one delay. The instrument measures the delay. It doesn''t get to measure someone''s faith.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "Both records use the same listening position. Their delay matches the channel interval. The claimed messages vary, while the recorded waveform repeats.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "Two supposed prophetic replies share the same drainage interval. Iren can explain the repetition without adjudicating anyone''s faith.", "options": [{"text": "Publish a narrow acoustic finding", "next": "choice_1", "action": ""}, {"text": "Co-author the explanation with custodians", "next": "choice_2", "action": ""}, {"text": "Archive raw traces for later review", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: The record corrects only what was measured. The cost is clear: Dramatic claims remain outside its scope.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: Observation and oral interpretation are attributed separately. The cost is clear: Agreement takes time.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: Others can inspect the evidence without inheriting a verdict. The cost is clear: The public gets no quick conclusion.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Recover the Drainage Interval Record from Quiet Gallery Rift Beast in Quiet Resonator Gallery. Examine Wrapped Resonator Rib and compare its evidence. Examine Drainage Listening Bench and compare its evidence. Discuss your finding with Iren Saye in Quiet Resonator Gallery.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 846)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_quiet_silence_kept', 'mq_quiet_silence_kept', 'npc_mystery_iren_saye', 'greeting', '[{"id": "greeting", "text": "I came for a complete explanation. I can leave with a careful one. Who should hold the next permission slip?", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "The cloth is a physical intervention. The bench reveals a reflection path. The repeated interval supports a limited finding, not an account of Shard intention.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "The gallery can become a public experiment, a conserved listening place, or a jointly stewarded archive. Iren asks who may decide its next use.", "options": [{"text": "Conserve it as a listening place", "next": "choice_1", "action": ""}, {"text": "Permit supervised public comparisons", "next": "choice_2", "action": ""}, {"text": "Create a jointly governed evidence archive", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: The bench and wrapping remain undisturbed. The cost is clear: New experiments become exceptional.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: Visitors may hear the measured effect for themselves. The cost is clear: Custodians must manage visitor pressure.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: The traces remain available under shared permission. The cost is clear: Neither group has unilateral authority.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Examine Wrapped Resonator Rib and compare its evidence. Examine Drainage Listening Bench and compare its evidence. Discuss your finding with Iren Saye in Quiet Resonator Gallery.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 847)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mystery_armistice_greet', NULL, 'npc_mystery_maela_orr', 'greet', '[{"id": "greet", "text": "A finding has a boundary. Write it down. New lock bolts hold an old stone cabinet shut. A scorched relief ledger sits beside an undamaged metal duplicate, both bearing the same modern custody mark.", "options": [{"text": "What did you notice here?", "next": "observation", "action": ""}, {"text": "Why ask an outsider?", "next": "motive", "action": ""}, {"text": "I will look around first.", "next": "exit", "action": "exit"}]}, {"id": "observation", "text": "The lock uses a current custody mark.", "options": [{"text": "Tell me more.", "next": "greet", "action": ""}, {"text": "I will examine it.", "next": "exit", "action": "exit"}]}, {"id": "motive", "text": "Maela holds a limited mandate to compare a recent neutral relief archive with scattered field copies. She needs a witness outside its Custodian and AMA sponsors because both have an interest in appearing blameless.", "options": [{"text": "What did you notice?", "next": "observation", "action": ""}, {"text": "I will think about it.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The evidence remains available when you return.", "options": []}]'::jsonb, 'dialog_tree_master.json', 124)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_npc_mystery_armistice_clue_1', NULL, 'npc_mystery_armistice_clue_1', 'greet', '[{"id": "greet", "text": "New lock bolts hold an old stone cabinet shut. A scorched relief ledger sits beside an undamaged metal duplicate, both bearing the same modern custody mark.", "options": [{"text": "Examine the mark.", "next": "detail", "action": ""}, {"text": "Compare its placement.", "next": "placement", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "detail", "text": "Scorching is strongest beside the nesting recess.", "options": [{"text": "Look at its setting.", "next": "placement", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "placement", "text": "New lock bolts hold an old stone cabinet shut. A scorched relief ledger sits beside an undamaged metal duplicate, both bearing the same modern custody mark.", "options": [{"text": "Look again.", "next": "greet", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The record is left in place.", "options": []}]'::jsonb, 'dialog_tree_master.json', 125)
