insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_npc_mystery_armistice_clue_2', NULL, 'npc_mystery_armistice_clue_2', 'greet', '[{"id": "greet", "text": "The duplicate plate survives across the chamber.", "options": [{"text": "Examine the mark.", "next": "detail", "action": ""}, {"text": "Compare its placement.", "next": "placement", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "detail", "text": "The duplicate plate survives across the chamber.", "options": [{"text": "Look at its setting.", "next": "placement", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "placement", "text": "New lock bolts hold an old stone cabinet shut. A scorched relief ledger sits beside an undamaged metal duplicate, both bearing the same modern custody mark.", "options": [{"text": "Look again.", "next": "greet", "action": ""}, {"text": "Step away.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The record is left in place.", "options": []}]'::jsonb, 'dialog_tree_master.json', 126)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_armistice_modern_lock', 'mq_armistice_modern_lock', 'npc_mystery_maela_orr', 'greeting', '[{"id": "greeting", "text": "The chamber is old. The lock is not. Please don''t turn a relief office into the missing chapter of the Severance.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "The lock uses a current custody mark. The ledger names a recent relief interval. Ancient stone wear continues beneath fresh bolt heads.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "A modern custody lock conceals a relief archive inside an ancient chamber. Maela needs the two histories separated before rumors combine them.", "options": [{"text": "Label both histories separately", "next": "choice_1", "action": ""}, {"text": "Prioritize the relief archive''s custody", "next": "choice_2", "action": ""}, {"text": "Request separate archaeological review", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: The cabinet gains distinct structure and archive labels. The cost is clear: Visitors get a less dramatic account.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: Immediate care protects the modern records. The cost is clear: The chamber''s past remains unexplored.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: A second inquiry examines the stone without conflating it with the ledger. The cost is clear: Review delays a complete site account.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Recover the Scorched Relief Ledger Leaf from Vault Ember Drakonid in Sealed Armistice Vault. Examine Scorched Relief Ledger and compare its evidence. Examine Duplicate Custody Plate and compare its evidence. Discuss your finding with Maela Orr in Sealed Armistice Vault.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 848)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_armistice_burn_without_verdict', 'mq_armistice_burn_without_verdict', 'npc_mystery_maela_orr', 'greeting', '[{"id": "greeting", "text": "A damaged ledger is evidence of damage. Motive needs another page.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "Scorching is strongest beside the nesting recess. The duplicate plate survives across the chamber. The custody mark is unchanged on both versions.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "Heat damage resembles deliberate destruction, but its pattern could come from a displaced beast nesting beside the cabinet.", "options": [{"text": "Publish the damage pattern", "next": "choice_1", "action": ""}, {"text": "Restrict interpretation until inspection", "next": "choice_2", "action": ""}, {"text": "Invite external custody witnesses", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: The report describes observed heat without assigning motive. The cost is clear: Readers may still demand an immediate culprit.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: A provisional report explicitly withholds a verdict. The cost is clear: People wait longer for an account.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: Independent witnesses inspect the same physical evidence. The cost is clear: The archive opens to more scrutiny.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Examine Scorched Relief Ledger and compare its evidence. Examine Duplicate Custody Plate and compare its evidence. Discuss your finding with Maela Orr in Sealed Armistice Vault.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 849)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_armistice_safe_for_copy', 'mq_armistice_safe_for_copy', 'npc_mystery_maela_orr', 'greeting', '[{"id": "greeting", "text": "A dead archivist can''t testify. Clear the immediate threat; we''ll keep the report about what you actually found.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "Fresh ember marks align with the nesting recess. The drakonid has no custody token or institutional mark. The duplicate survives independently of the damaged page.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "The nesting drakonid threatens anyone copying the relief records. Maela needs a safe chamber before commissioning an audit.", "options": [{"text": "Copy the duplicate first", "next": "choice_1", "action": ""}, {"text": "Stabilize the fragile pages first", "next": "choice_2", "action": ""}, {"text": "Have two witnesses divide the copying", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: The audit gains a stable control record. The cost is clear: Damaged personal entries wait.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: The most vulnerable record receives priority. The cost is clear: The control copy waits.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: Copies begin with independent chains of custody. The cost is clear: More staff and supplies are needed.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Stop the dangerous Vault Ember Drakonid in Sealed Armistice Vault. Inspect the now-safe evidence area in Sealed Armistice Vault. Examine Scorched Relief Ledger and compare its evidence. Examine Duplicate Custody Plate and compare its evidence. Discuss your finding with Maela Orr in Sealed Armistice Vault.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 850)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_armistice_reserve_not_ransom', 'mq_armistice_reserve_not_ransom', 'npc_mystery_maela_orr', 'greeting', '[{"id": "greeting", "text": "AMA''s wording is exact. A hungry household doesn''t eat exact wording. Verify the reserve and keep the delay in the finding.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "The reserve line names an unsettled transfer. The duplicate has a release condition but no faction-concession clause. A field note records recipients waiting while settlement was checked.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "A line called withheld reserve looks like relief money seized as leverage. The duplicate identifies an unsettled payment, while leaving the delay''s human cost visible.", "options": [{"text": "Publish both the settlement reason and delay", "next": "choice_1", "action": ""}, {"text": "Request an emergency relief exception", "next": "choice_2", "action": ""}, {"text": "Seek independent review of the hold", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: The record preserves the cost borne by recipients. The cost is clear: Sponsors face criticism despite a valid accounting category.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: A narrow exception request accompanies the audited account. The cost is clear: The authority must accept additional settlement risk.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: A neutral review tests whether the hold was proportionate. The cost is clear: Release may be further delayed.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Recover the Modern Custody Duplicate from Vault Ember Drakonid in Sealed Armistice Vault. Examine Scorched Relief Ledger and compare its evidence. Examine Duplicate Custody Plate and compare its evidence. Discuss your finding with Maela Orr in Sealed Armistice Vault.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 851)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_mq_armistice_unwritten_witness', 'mq_armistice_unwritten_witness', 'npc_mystery_maela_orr', 'greeting', '[{"id": "greeting", "text": "Five places. Five ways a neat record can injure someone. I can''t award you the truth about Xylos. I can ask who gets to correct this shelf after us.", "options": [{"text": "Show me what the evidence actually says.", "next": "evidence", "action": ""}, {"text": "Who pays the cost of our decision?", "next": "decision", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "evidence", "text": "The ward separates recognition from disclosure; the yard separates absence from desertion. The berth separates a valid unit from a duplicate charge; the gallery separates sound from intention. The vault separates accounting accuracy from the consequences of delay.", "options": [{"text": "What are our options?", "next": "decision", "action": ""}, {"text": "I will investigate.", "next": "accept", "action": ""}, {"text": "I will return later.", "next": "exit", "action": "exit"}]}, {"id": "decision", "text": "Records from the ward, yard, berth, gallery, and vault show how institutions can mistake absence, silence, or delay for consent. Maela offers no revelation about a hidden ruler, only a decision about who may challenge the archive.", "options": [{"text": "Create a public, redacted appeal index", "next": "choice_1", "action": ""}, {"text": "Establish distributed local custodians", "next": "choice_2", "action": ""}, {"text": "Create a rotating independent review", "next": "choice_3", "action": ""}, {"text": "I will not decide yet.", "next": "exit", "action": "exit"}]}, {"id": "choice_1", "text": "If we choose that: People can challenge entries without revealing protected identities. The cost is clear: Transparency needs careful privacy work.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_2", "text": "If we choose that: Each site keeps a voice in its own record. The cost is clear: Corrections are slower to reconcile.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "choice_3", "text": "If we choose that: No permanent sponsor owns the final interpretation. The cost is clear: Reviewers require resources and can still err.", "options": [{"text": "I will verify the evidence first.", "next": "accept", "action": ""}, {"text": "I need more time.", "next": "exit", "action": "exit"}]}, {"id": "accept", "text": "Keep these points separate: Examine Scorched Relief Ledger and compare its evidence. Examine Duplicate Custody Plate and compare its evidence. Discuss your finding with Maela Orr in Sealed Armistice Vault.", "options": [{"text": "Begin this investigation.", "next": "exit", "action": "accept_quest"}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "You may return without losing your place in the investigation.", "options": []}]'::jsonb, 'dialog_quests.json', 852)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
do $mystery_pack$
begin
 if (select count(*) from public.quests where id in ('mq_unlisted_two_chairs','mq_unlisted_second_number','mq_unlisted_obedient_lock','mq_unlisted_folded_route','mq_unlisted_right_to_remain','mq_muster_fourth_beat','mq_muster_boots_outward','mq_muster_cable_thief','mq_muster_shared_shift','mq_muster_warning_not_oath','mq_zero_weight_nothing','mq_zero_inside_label','mq_zero_fee_at_door','mq_zero_rent_inside_rent','mq_zero_port_without_lie','mq_quiet_cloth_on_crystal','mq_quiet_bench_wrong_way','mq_quiet_test_without_beast','mq_quiet_same_pause','mq_quiet_silence_kept','mq_armistice_modern_lock','mq_armistice_burn_without_verdict','mq_armistice_safe_for_copy','mq_armistice_reserve_not_ransom','mq_armistice_unwritten_witness')) <> 25 then raise exception 'Mystery quests missing'; end if;
 if exists (select 1 from public.monsters m cross join lateral jsonb_array_elements(m.drop_item) d left join public.items i on i.id=d->>'itemId' where m.monster_id in (6101,6102,6103,6104,6105) and i.id is null) then raise exception 'Mystery clue item missing'; end if;
 if exists (select 1 from public.monsters m cross join lateral jsonb_array_elements(m.skill_set->'active_skills') r left join public.skills s on s.id=r->>'skill_id' where m.monster_id in (6101,6102,6103,6104,6105) and (s.id is null or s.type<>'Active')) then raise exception 'Mystery active skill invalid'; end if;
 if exists (select 1 from public.monsters m cross join lateral jsonb_array_elements(m.skill_set->'passive_skills') r left join public.skills s on s.id=r->>'skill_id' where m.monster_id in (6101,6102,6103,6104,6105) and (s.id is null or s.type<>'Passive')) then raise exception 'Mystery passive skill invalid'; end if;
 if exists (select 1 from public.quests q left join public.npcs n on n.npc_id=q.quest_giver->>'npc_id' where q.id in ('mq_unlisted_two_chairs','mq_unlisted_second_number','mq_unlisted_obedient_lock','mq_unlisted_folded_route','mq_unlisted_right_to_remain','mq_muster_fourth_beat','mq_muster_boots_outward','mq_muster_cable_thief','mq_muster_shared_shift','mq_muster_warning_not_oath','mq_zero_weight_nothing','mq_zero_inside_label','mq_zero_fee_at_door','mq_zero_rent_inside_rent','mq_zero_port_without_lie','mq_quiet_cloth_on_crystal','mq_quiet_bench_wrong_way','mq_quiet_test_without_beast','mq_quiet_same_pause','mq_quiet_silence_kept','mq_armistice_modern_lock','mq_armistice_burn_without_verdict','mq_armistice_safe_for_copy','mq_armistice_reserve_not_ransom','mq_armistice_unwritten_witness') and n.npc_id is null) then raise exception 'Mystery giver missing'; end if;
 if exists (select 1 from public.quests q cross join lateral jsonb_array_elements(q.rewards->'items') r left join public.items i on i.id=r->>'item_id' where q.id in ('mq_unlisted_two_chairs','mq_unlisted_second_number','mq_unlisted_obedient_lock','mq_unlisted_folded_route','mq_unlisted_right_to_remain','mq_muster_fourth_beat','mq_muster_boots_outward','mq_muster_cable_thief','mq_muster_shared_shift','mq_muster_warning_not_oath','mq_zero_weight_nothing','mq_zero_inside_label','mq_zero_fee_at_door','mq_zero_rent_inside_rent','mq_zero_port_without_lie','mq_quiet_cloth_on_crystal','mq_quiet_bench_wrong_way','mq_quiet_test_without_beast','mq_quiet_same_pause','mq_quiet_silence_kept','mq_armistice_modern_lock','mq_armistice_burn_without_verdict','mq_armistice_safe_for_copy','mq_armistice_reserve_not_ransom','mq_armistice_unwritten_witness') and i.id is null) then raise exception 'Mystery reward missing'; end if;
end;
$mystery_pack$;
commit;
